rows=json.loads((folder/'additions.json').read_text())
byfile={}
for r in rows:
 if r['card']['id'] not in updates:continue
 source,line=r['editorial']['source_row'].split(':');byfile.setdefault(source,[]).append((int(line)-1,updates[r['card']['id']]))
for source,changes in byfile.items():
 p=folder/source;lines=p.read_text().splitlines()
 for line,(q,d,reason) in changes:
  cols=[x.strip() for x in lines[line].split('|')];cols[1]=q;cols[2]=d;cols[6]=reason;lines[line]=' | '.join(cols)
 p.write_text('\n'.join(lines)+'\n')
(folder/'refinement-log.json').write_text(json.dumps({'date':'2026-10-08','reviewed_cards':663,'revisions':[{ 'id':r['card']['id'],'before':r['card']['question'],'after':updates[r['card']['id']][0]} for r in rows if r['card']['id'] in updates]},ensure_ascii=False,indent=2)+'\n')
print(len(updates),'revisions')
